cy.addProductsToCart(2);
cy.url().should("include", "/sepet");
let productsTotal = 0;
cy.get(_ShoppingCartPage.default.cartItems).find("strong").filter((index, element) => {
  return element.innerText.trim() === "Toplam";
}).next(".price-sell").each($price => {
  const price = parsePrice($price.text());
  productsTotal += price;
}).then(() => {
  cy.get(_ShoppingCartPage.default.cartPriceContainer).contains("Sepet Toplamı").parent().find(".text-right").invoke("text").then(cartTotalText => {
    const cartTotal = parsePrice(cartTotalText);
    expect(productsTotal).to.eq(cartTotal);
  });
});

let expectedProductName;
let expectedUnitPrice;
cy.get(_SearchPage.default.productCards).first().then($card => {
  expectedProductName = $card.find(_SearchPage.default.productName).text().trim();
  expectedUnitPrice = parsePrice($card.find(_SearchPage.default.productPrice).text());
  cy.addProductsToCart(1);
  cy.get(_ShoppingCartPage.default.cartItems).contains(expectedProductName).closest(_ShoppingCartPage.default.cartItems).then($item => {
    cy.wrap($item).find(_ShoppingCartPage.default.productName).invoke("text").then(cartProductName => {
      expect(cartProductName.trim()).to.eq(expectedProductName);
    });
    cy.wrap($item).find(_ShoppingCartPage.default.priceValue).should("have.length", 2).then($prices => {
      const unitPrice = parsePrice($prices.eq(0).text());
      const totalPrice = parsePrice($prices.eq(1).text());
      expect(unitPrice).to.eq(expectedUnitPrice);
      cy.wrap($item).find(_ShoppingCartPage.default.productQuantity).invoke("val").then(quantityValue => {
        const quantity = Number(quantityValue);
        expect(quantity).to.be.at.least(1);
        expect(totalPrice).to.eq(unitPrice * quantity);
      });
    });
  });
});

