cy.addProductsToCart(1);
cy.get(_ShoppingCartPage.default.cartItems).first().then($item => {
  cy.wrap($item).find(_ShoppingCartPage.default.productQuantity).invoke("val").then(quantityValue => {
    const initialQuantity = Number(quantityValue);
    cy.wrap($item).contains("strong", "Fiyat").parent().find(".price-sell").invoke("text").then(unitPriceText => {
      const unitPrice = parsePrice(unitPriceText);
      cy.get(_ShoppingCartPage.default.cartPriceContainer).find(_ShoppingCartPage.default.cartPriceRows).eq(0).find(".text-right").invoke("text").then(subtotalText => {
        const initialSubtotal = parsePrice(subtotalText);
        cy.wrap($item).find(_ShoppingCartPage.default.increaseQuantityButton).click();
        cy.get(_ShoppingCartPage.default.cartItems).first().find(_ShoppingCartPage.default.productQuantity).should("have.value", String(initialQuantity + 1));
        cy.get(_ShoppingCartPage.default.cartPriceContainer).find(_ShoppingCartPage.default.cartPriceRows).eq(0).find(".text-right").should($subtotal => {
          const newSubtotal = parsePrice($subtotal.text());
          expect(newSubtotal).to.eq(initialSubtotal + unitPrice);
        });
      });
    });
  });
});

